{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Bucket missing Public Access Block",
      "resource": "aws_s3_bucket.logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have a public access block configured, which is a critical security control to prevent accidental or malicious public exposure of log data."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Disabled",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not enabled for this bucket. Even though it is a logs bucket, enabling access logging provides an audit trail of who accessed the logs themselves."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 Bucket Lifecycle Configuration Missing",
      "resource": "aws_s3_bucket.logs",
      "severity": "LOW",
      "explanation": "No lifecycle rules are defined. For a logs bucket, it is best practice to define expiration rules to manage storage costs and retention policies automatically."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "expire-logs"
    status = "Enabled"

    expiration {
      days = 90
    }
  }
}

resource "aws_s3_bucket_logging" "logs" {
  bucket        = aws_s3_bucket.logs.id
  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "access-logs/"
}",
  "fix_summary": "Added `aws_s3_bucket_public_access_block` to enforce strict public access controls. Added `aws_s3_bucket_lifecycle_configuration` with a 90-day expiration rule to manage log retention. Added `aws_s3_bucket_logging` to enable server access logging for the bucket itself."
}
